build_sparql.sparql:
PREFIX dblp: <https://dblp.org/rdf/schema#>
SELECT ?number_of_authors WHERE {
  ?publ dblp:title ?title .
  FILTER CONTAINS (?title, "NFDI4DS Gateway and Portal.")
  ?publ dblp:numberOfCreators ?number_of_authors . 
}

PREFIX dblp: <https://dblp.org/rdf/schema#>
SELECT (COUNT(?author) AS ?numberOfAuthors) WHERE {
  ?publication dblp:title ?title .
  FILTER CONTAINS (?title, "NFDI4DS Gateway and Portal") .
  ?publication <https://dblp.org/rdf/schema#authoredBy> ?author .
}

PREFIX dblp: <https://dblp.org/rdf/schema#>
SELECT (FLOOR(AVG(?countPerYear)) AS ?averagePublicationsPerYear)
WHERE {
  {
    SELECT ?year (COUNT(DISTINCT ?paper) AS ?countPerYear)
    WHERE {
      ?author dblp:creatorName ?author_name .
      FILTER CONTAINS( ?author_name, "Hannah Bast" )
      ?paper dblp:authoredBy ?author . 
      ?paper dblp:yearOfPublication ?year .
    }
    GROUP BY ?year
  }
}
